// - malloc/realloc/calloc/free directly wrap the C runtime counterparts
// - aligned_malloc/aligned_free form a matched pair using a header to store the base pointer
//   ensuring no mismatch with the CRT and avoiding recursion into roaring_* APIs
roaring_memory_t hook{};

hook.malloc = +[](size_t n) -> void* {
    return ::malloc(n);
};

hook.realloc = +[](void* p, size_t n) -> void* {
    return ::realloc(p, n);
};

hook.calloc = +[](size_t cnt, size_t sz) -> void* {
    // Basic overflow guard: if cnt != 0 and sz > SIZE_MAX / cnt, return NULL
    if (cnt != 0 && sz > (SIZE_MAX / cnt)) return nullptr;
    return ::calloc(cnt, sz);
};

hook.free = +[](void* p) -> void {
    ::free(p);
};

hook.aligned_malloc = +[](size_t alignment, size_t size) -> void* {
    // Enforce power-of-two alignment and at least sizeof(void*)
    if (alignment < sizeof(void*)) alignment = sizeof(void*);
    // round alignment to next power of two
    size_t a = alignment;
